"""
Lab solution: Failure Types, Backoff with Jitter, Retries, a Circuit Breaker, and Alerts
Standard library only.
"""
import random

TRANSIENT_STATUS = {408, 425, 429, 500, 502, 503, 504, 529}
PERMANENT_STATUS = {400, 401, 403, 404, 405, 409, 410, 413, 422}
TRANSIENT_ERRORS = {"timeout", "connection_reset", "dns_failure"}


def scripted(*outcomes):
    """Given: a fake task that returns the outcomes in order, repeating the last one."""
    return lambda attempt: outcomes[min(attempt, len(outcomes) - 1)]


# ---------------------------------------------------------------- Step 1
def classify(failure):
    """Retry what may succeed later; stop on what will fail the same way; send bad data to a person.
    Unknown failures are treated as permanent, so a person looks rather than a loop retrying."""
    if failure.get("kind") == "validation":
        return "data"
    if failure.get("error") in TRANSIENT_ERRORS:
        return "transient"
    status = failure.get("status")
    if status in TRANSIENT_STATUS:
        return "transient"
    if status in PERMANENT_STATUS:
        return "permanent"
    if status is not None and 500 <= status < 600:
        return "transient"
    return "permanent"


# ---------------------------------------------------------------- Step 2
def backoff(attempt, base=1.0, cap=32.0, rng=None, jitter="full"):
    """Exponential ceiling, capped; jitter spreads clients so they do not retry in waves."""
    ceiling = min(cap, base * 2 ** attempt)
    if jitter == "none":
        return ceiling
    if jitter == "full":
        return rng.uniform(0, ceiling)
    if jitter == "equal":
        return ceiling / 2 + rng.uniform(0, ceiling / 2)
    raise ValueError("unknown jitter: " + jitter)


# ---------------------------------------------------------------- Step 3
def run_with_retries(task, is_transient, wait_for, max_attempts=5):
    """Retry only transient failures, wait between attempts but not after the last,
    and dead-letter everything else rather than dropping it."""
    waits = []
    for attempt in range(max_attempts):
        outcome = task(attempt)
        if outcome.get("ok"):
            return {"status": "done", "attempts": attempt + 1, "waits": waits, "result": outcome.get("result")}
        if not is_transient(outcome):
            return {"status": "dead_letter", "attempts": attempt + 1, "waits": waits, "reason": "not retryable"}
        if attempt < max_attempts - 1:
            waits.append(wait_for(attempt))
    return {"status": "dead_letter", "attempts": max_attempts, "waits": waits, "reason": "exhausted"}


# ---------------------------------------------------------------- Step 4
class Breaker:
    """Closed: calls pass. Open: calls refused. Half-open after the cooldown: one trial decides."""

    def __init__(self, threshold=3, cooldown=60):
        self.threshold, self.cooldown = threshold, cooldown
        self.failures, self.state, self.opened_at = 0, "closed", None

    def allow(self, now):
        if self.state == "open" and now - self.opened_at >= self.cooldown:
            self.state = "half_open"
        return self.state != "open"

    def record(self, ok, now):
        if ok:
            self.failures, self.state = 0, "closed"
        else:
            self.failures += 1
            if self.state == "half_open" or self.failures >= self.threshold:
                self.state, self.opened_at = "open", now


# ---------------------------------------------------------------- Step 5
def should_alert(failures, now, window=300, threshold=5, last_alert=None, cooldown=1800):
    """Alert on a rate over a window, once per incident, so the channel stays worth reading."""
    recent = [moment for moment in failures if now - window < moment <= now]
    if len(recent) < threshold:
        return False, len(recent)
    if last_alert is not None and now - last_alert < cooldown:
        return False, len(recent)
    return True, len(recent)


if __name__ == "__main__":
    for failure in ({"status": 429}, {"status": 401}, {"error": "timeout"}, {"kind": "validation"}, {"status": 418}):
        print(failure, classify(failure))
    print([backoff(n, jitter="none") for n in range(7)])
    generator = random.Random(7)
    print([round(backoff(n, rng=generator), 3) for n in range(6)])
    print([backoff(n, base=2, cap=60, jitter="none") for n in range(7)])
    transient = lambda outcome: classify(outcome) == "transient"
    plain = lambda attempt: backoff(attempt, jitter="none")
    print(run_with_retries(scripted({"status": 503}, {"status": 503}, {"ok": True, "result": "invoice-77"}), transient, plain))
    print(run_with_retries(scripted({"status": 503}), transient, plain, max_attempts=4))
    breaker = Breaker()
    for now, ok in [(0, False), (5, False), (10, False)]:
        breaker.record(ok, now)
    print(breaker.state, breaker.allow(20), breaker.allow(70), breaker.state)
    print(should_alert([100, 130, 160, 200, 240, 250], 260), should_alert([100, 130, 160, 200, 240, 250], 260, last_alert=0))
